INSERT INTO `tutores` (`id_tutor`, `id_usuario`, `especialidad`, `biografia`) VALUES (1,3,'Matemática aplicada','Ingeniero civil con maestría en Matemática Aplicada (UAGRM). Docente de ciencias básicas desde 2014.'),(2,4,'Programación y algoritmos','Ingeniera de sistemas, desarrolladora backend en Java y Python. Tutora de programación desde 2021.'),(3,5,'Bases de datos','Ingeniero de sistemas, DBA en una entidad financiera local. Certificado Oracle Database SQL.'),(4,6,'Redes y sistemas operativos','Ingeniera en redes, certificada CCNA. Administra infraestructura de servidores Linux.'),(5,7,'Física','Licenciado en Física. Docente de Física I y II en ingenierías.'),(6,8,'Contabilidad','Contadora pública autorizada, auditora externa. Docente de contabilidad desde 2016.'),(7,9,'Estadística y finanzas','Economista con diplomado en Finanzas. Analista de riesgos en banca.'),(8,10,'Economía','Licenciada en Economía con maestría en Gestión Empresarial.'),(9,11,'Derecho civil y constitucional','Abogado litigante. Magíster en Derecho Constitucional.'),(10,12,'Derecho penal','Abogada, ex fiscal de materia. Docente de Derecho Penal.'),(11,13,'Psicología del desarrollo','Psicóloga clínica infantil. Magíster en Psicología Educativa.'),(12,14,'Administración','Administrador de empresas, gerente de RR.HH. en el sector agroindustrial.'),(13,15,'Ingeniería de software','Ingeniero de sistemas, líder técnico en una software factory. Scrum Master certificado.'),(14,16,'Investigación y psicometría','Psicóloga organizacional. Investigadora en evaluación psicométrica.'),(15,17,'Tributación y auditoría','Contadora pública, especialista en tributación boliviana (SIN).'),(16,18,'Investigación operativa','Ingeniero industrial. Actualmente con licencia académica.'),(17,19,'Desarrollo web','Ingeniero de sistemas egresado de UPDS. Se incorporó al programa de tutorías en septiembre de 2026.');
